mapper.select:
SELECT 

WHERE 1 = 1

    AND EXISTS (
        SELECT 1
        FROM resident_meter AS binding
        WHERE binding.resident_id = #{residentId}
          AND binding.meter_id = record.meter_id
    )


    AND (
        task.task_no LIKE CONCAT('%', #{keyword}, '%')
        OR meter.meter_no LIKE CONCAT('%', #{keyword}, '%')
        OR meter.meter_name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND record.meter_id = #{meterId}


    AND record.source_type = #{sourceType}


    AND record.reading_at >= #{readingAtStart}


    AND record.reading_at <= #{readingAtEnd}

ORDER BY record.reading_at DESC, record.id DESC

SELECT 

WHERE record.id = #{recordId}

    AND EXISTS (
        SELECT 1
        FROM resident_meter AS binding
        WHERE binding.resident_id = #{residentId}
          AND binding.meter_id = record.meter_id
    )

LIMIT 1
